function ActivityMidFestivalTaskDialog:InitHandler()
    ---@type ActivityMidFestivalComponent
    self._activityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    self.events[Constants.EventNames.ActivityMidFestivalTaskReq] = Events.AddListener(Constants.EventNames.ActivityMidFestivalTaskReq, Bind(self, self.OnEventTaskReqHandler))
    self.events[Constants.EventNames.ActivityMidFestivalDrawTaskRewardReq] = Events.AddListener(Constants.EventNames.ActivityMidFestivalDrawTaskRewardReq, Bind(self, self.OnEventDrawTaskRewardReqHandler))
