--region handler
function ActivityMidFestivalTaskDialog:OnEventDrawTaskRewardReqHandler()
    self:InitData()
end

function ActivityMidFestivalTaskDialog:OnEventTaskReqHandler()
    self._isWaiting = false
    self._taskDojo = self._activityComponent:GetTaskDojo()
    self._tasksList = {}

    for k, v in pairs(self._taskDojo.task) do
        table.insert(self._tasksList, v)
    end

    local priority = {
        [Constants.MidFestivalShopProductCellStatus.CAN_DRAW] = 1,      -- 可领取优先
        [Constants.MidFestivalShopProductCellStatus.UNDER_PROCESS] = 2, -- 进行中
        [Constants.MidFestivalShopProductCellStatus.IS_DRAW] = 3,       -- 已领取
    }
    -- 排序
    table.sort(self._tasksList, function(a, b)
        if priority[a.status] == priority[b.status] then
            return a.id < b.id
        end
        return priority[a.status] < priority[b.status]
    end)
    self:RefreshUI()
end
--endregion handler

--region private
function ActivityMidFestivalTaskDialog:RefreshItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._tasksList[luaIndex]
    local cell = listView:NewListViewItem("CellNode")
    ---@type ActivityMidFestivalTaskCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.MidFestival.TaskDialog.ActivityMidFestivalTaskCell")
    scr:Refresh(cellData)
    if luaIndex <= listView.DisplayItemCount then
        CfUtils.PlayDelayShowAnimation(cell, index)
    end
    return cell
end

function ActivityMidFestivalTaskDialog:RefreshUI()
    local taskCount = table.count(self._tasksList)
    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(taskCount, Bind(self, self.RefreshItemByIndex))
        self.ListView:UpdateDisplayItemCount("CellNode")
    else
        GameUtils.ReloadData(self.ListView, taskCount)
    end
end
--endregion private

